/*
 * High-performance portfolio calculations using C extension.
 *
 * Supports both NumPy arrays (zero-copy, contiguous float64) and ordinary
 * Python sequences (list of lists) without an expensive full conversion.
 * The arithmetic order matches the pure-Python baseline.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static inline double item_to_double(PyObject *item) {
    if (PyFloat_CheckExact(item))
        return PyFloat_AS_DOUBLE(item);
    return PyFloat_AsDouble(item);
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    npy_intp n;

    if (PyArray_Check(weights_obj)) {
        PyArrayObject *w = (PyArrayObject *)weights_obj;
        if (PyArray_NDIM(w) != 1 || PyArray_TYPE(w) != NPY_DOUBLE ||
            !PyArray_IS_C_CONTIGUOUS(w)) {
            PyErr_SetString(PyExc_ValueError,
                            "weights must be a contiguous 1D float64 array");
            return NULL;
        }
        n = PyArray_DIM(w, 0);
    } else {
        Py_ssize_t size = PySequence_Size(weights_obj);
        if (size < 0) {
            PyErr_SetString(PyExc_ValueError, "weights must be a sequence");
            return NULL;
        }
        n = (npy_intp)size;
    }

    if (PyArray_Check(cov_obj)) {
        PyArrayObject *cov = (PyArrayObject *)cov_obj;
        if (PyArray_NDIM(cov) != 2 || PyArray_TYPE(cov) != NPY_DOUBLE ||
            !PyArray_IS_C_CONTIGUOUS(cov)) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix must be a contiguous 2D float64 array");
            return NULL;
        }
        if (PyArray_DIM(cov, 0) != n || PyArray_DIM(cov, 1) != n) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix dimensions must match weights length");
            return NULL;
        }
    } else {
        Py_ssize_t rows = PySequence_Size(cov_obj);
        if (rows != (Py_ssize_t)n) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix dimensions must match weights length");
            return NULL;
        }
    }

    double *temp = (double *)malloc((size_t)n * sizeof(double));
    if (temp == NULL && n > 0) {
        PyErr_NoMemory();
        return NULL;
    }

    if (PyArray_Check(weights_obj) && PyArray_Check(cov_obj)) {
        const double *weights = (const double *)PyArray_DATA((PyArrayObject *)weights_obj);
        const double *cov = (const double *)PyArray_DATA((PyArrayObject *)cov_obj);

        for (npy_intp i = 0; i < n; ++i) {
            const double *row = cov + i * n;
            double row_sum = 0.0;
            for (npy_intp j = 0; j < n; ++j)
                row_sum += row[j] * weights[j];
            temp[i] = row_sum;
        }

        double risk_squared = 0.0;
        for (npy_intp i = 0; i < n; ++i)
            risk_squared += weights[i] * temp[i];

        free(temp);
        return PyFloat_FromDouble(sqrt(risk_squared));
    }

    /* Generic Python-sequence path (list of lists, tuple of tuples, ...). */
    PyObject *weights_fast = PySequence_Fast(weights_obj, "weights must be a sequence");
    if (weights_fast == NULL) {
        free(temp);
        return NULL;
    }
    PyObject **weights = PySequence_Fast_ITEMS(weights_fast);

    PyObject *cov_fast = PySequence_Fast(cov_obj, "cov_matrix must be a sequence");
    if (cov_fast == NULL) {
        Py_DECREF(weights_fast);
        free(temp);
        return NULL;
    }
    PyObject **rows = PySequence_Fast_ITEMS(cov_fast);

    int failed = 0;
    for (npy_intp i = 0; i < n; ++i) {
        PyObject *row_fast = PySequence_Fast(rows[i], "covariance row must be a sequence");
        if (row_fast == NULL) {
            failed = 1;
            break;
        }
        if (PySequence_Fast_GET_SIZE(row_fast) != (Py_ssize_t)n) {
            Py_DECREF(row_fast);
            PyErr_SetString(PyExc_ValueError, "covariance rows must match weights length");
            failed = 1;
            break;
        }
        PyObject **row = PySequence_Fast_ITEMS(row_fast);
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j)
            row_sum += item_to_double(row[j]) * item_to_double(weights[j]);
        temp[i] = row_sum;
        Py_DECREF(row_fast);
    }

    double risk_squared = 0.0;
    if (!failed) {
        for (npy_intp i = 0; i < n; ++i)
            risk_squared += item_to_double(weights[i]) * temp[i];
    }

    Py_DECREF(weights_fast);
    Py_DECREF(cov_fast);
    free(temp);

    if (failed) {
        if (!PyErr_Occurred())
            PyErr_SetString(PyExc_ValueError, "invalid covariance matrix");
        return NULL;
    }

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    npy_intp n;

    if (PyArray_Check(weights_obj)) {
        PyArrayObject *w = (PyArrayObject *)weights_obj;
        if (PyArray_NDIM(w) != 1 || PyArray_TYPE(w) != NPY_DOUBLE ||
            !PyArray_IS_C_CONTIGUOUS(w)) {
            PyErr_SetString(PyExc_ValueError,
                            "weights must be a contiguous 1D float64 array");
            return NULL;
        }
        n = PyArray_DIM(w, 0);
    } else {
        Py_ssize_t size = PySequence_Size(weights_obj);
        if (size < 0) {
            PyErr_SetString(PyExc_ValueError, "weights must be a sequence");
            return NULL;
        }
        n = (npy_intp)size;
    }

    if (PyArray_Check(returns_obj)) {
        PyArrayObject *r = (PyArrayObject *)returns_obj;
        if (PyArray_NDIM(r) != 1 || PyArray_TYPE(r) != NPY_DOUBLE ||
            !PyArray_IS_C_CONTIGUOUS(r) || PyArray_DIM(r, 0) != n) {
            PyErr_SetString(PyExc_ValueError,
                            "expected_returns must be a contiguous 1D float64 array "
                            "matching weights length");
            return NULL;
        }
    } else {
        Py_ssize_t size = PySequence_Size(returns_obj);
        if (size != (Py_ssize_t)n) {
            PyErr_SetString(PyExc_ValueError,
                            "expected_returns length must match weights length");
            return NULL;
        }
    }

    if (PyArray_Check(weights_obj) && PyArray_Check(returns_obj)) {
        const double *weights = (const double *)PyArray_DATA((PyArrayObject *)weights_obj);
        const double *returns = (const double *)PyArray_DATA((PyArrayObject *)returns_obj);
        double total_return = 0.0;
        for (npy_intp i = 0; i < n; ++i)
            total_return += weights[i] * returns[i];
        return PyFloat_FromDouble(total_return);
    }

    PyObject *weights_fast = PySequence_Fast(weights_obj, "weights must be a sequence");
    if (weights_fast == NULL)
        return NULL;
    PyObject *returns_fast = PySequence_Fast(returns_obj,
                                             "expected_returns must be a sequence");
    if (returns_fast == NULL) {
        Py_DECREF(weights_fast);
        return NULL;
    }

    PyObject **weights = PySequence_Fast_ITEMS(weights_fast);
    PyObject **returns = PySequence_Fast_ITEMS(returns_fast);

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        total_return += item_to_double(weights[i]) * item_to_double(returns[i]);

    Py_DECREF(weights_fast);
    Py_DECREF(returns_fast);
    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
